-- =============================================================================
-- Migration 0037: K.2 Theorie A — Primitiveren en de productregel
-- =============================================================================
-- Gegenereerd door scripts/k2a-content.ts — niet met de hand bewerken.
--
-- Theorieblok A van K.2: partieel integreren. Uit de productregel volgt
-- int g * h' dx = g * h - int h * g' dx. Je primitiveert één factor (h') en
-- differentieert de andere (g); de keuze is goed als de overgebleven integraal
-- makkelijker is. Steeds één keer partieel integreren — twee keer is Theorie B.
--
-- Eigen oefenvragen, geen boekopgaven. Elke primitieve wordt nagerekend door
-- src/content/primitieven.test.ts (content/hoofdstuk-k/k2a.json).
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 3 topics, 6 clusters
--   • 36 vragen met elk 4 stappen (144 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k2a_partieel', $ksql$Primitiveren met partieel integreren$ksql$, 10, 'primitiveren'),
  ('k2a_bepaald', $ksql$Bepaalde integralen met partieel integreren$ksql$, 11, 'integralen'),
  ('k2a_toepassingen', $ksql$Oppervlakte met partieel integreren$ksql$, 12, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Een veelterm maal een sinus of cosinus$ksql$, 1),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Een veelterm maal een e-macht$ksql$, 2),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveren met een logaritme$ksql$, 3),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bepaalde integralen met gonio$ksql$, 1),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bepaalde integralen met e-machten en logaritmen$ksql$, 2),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Oppervlakte en p bepalen$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
