SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos(2x)$$ksql$, $ksql$x sin(2x)/2 + cos(2x)/4 + c$ksql$, $ksql$F(x) = \tfrac{1}{2}x\sin(2x) + \tfrac{1}{4}\cos(2x) + c$ksql$, 1, 1, ARRAY[$ksql$1/2 x sin(2x) + 1/4 cos(2x) + c$ksql$, $ksql$0,5x sin(2x) + 0,25cos(2x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = 4x\sin(x)$$ksql$, $ksql$-4x cos(x) + 4sin(x) + c$ksql$, $ksql$F(x) = -4x\cos(x) + 4\sin(x) + c$ksql$, 1, 2, ARRAY[$ksql$4sin(x) - 4x cos(x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (4x - 1)\cos(x)$$ksql$, $ksql$(4x - 1)sin(x) + 4cos(x) + c$ksql$, $ksql$F(x) = (4x - 1)\sin(x) + 4\cos(x) + c$ksql$, 2, 3, ARRAY[$ksql$4x sin(x) - sin(x) + 4cos(x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (2 - x)\sin(2x)$$ksql$, $ksql$-(2 - x)cos(2x)/2 - sin(2x)/4 + c$ksql$, $ksql$F(x) = -\tfrac{1}{2}(2 - x)\cos(2x) - \tfrac{1}{4}\sin(2x) + c$ksql$, 2, 4, ARRAY[$ksql$-1/2 (2 - x)cos(2x) - 1/4 sin(2x) + c$ksql$, $ksql$(x - 2)cos(2x)/2 - sin(2x)/4 + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(x)\cos(x)$$ksql$, $ksql$-x cos(2x)/4 + sin(2x)/8 + c$ksql$, $ksql$F(x) = -\tfrac{1}{4}x\cos(2x) + \tfrac{1}{8}\sin(2x) + c$ksql$, 3, 5, ARRAY[$ksql$-1/4 x cos(2x) + 1/8 sin(2x) + c$ksql$, $ksql$sin(2x)/8 - x cos(2x)/4 + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos^{2}(x)$$ksql$, $ksql$x^2/4 + x sin(2x)/4 + cos(2x)/8 + c$ksql$, $ksql$F(x) = \tfrac{1}{4}x^{2} + \tfrac{1}{4}x\sin(2x) + \tfrac{1}{8}\cos(2x) + c$ksql$, 3, 6, ARRAY[$ksql$1/4 x^2 + 1/4 x sin(2x) + 1/8 cos(2x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{3x}$$ksql$, $ksql$x e^(3x)/3 - e^(3x)/9 + c$ksql$, $ksql$F(x) = \tfrac{1}{3}x\mathrm{e}^{3x} - \tfrac{1}{9}\mathrm{e}^{3x} + c$ksql$, 1, 1, ARRAY[$ksql$1/3 x e^(3x) - 1/9 e^(3x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{-x}$$ksql$, $ksql$-(x + 1)e^(-x) + c$ksql$, $ksql$F(x) = -(x + 1)\mathrm{e}^{-x} + c$ksql$, 1, 2, ARRAY[$ksql$-x e^(-x) - e^(-x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x + 1)\mathrm{e}^{x}$$ksql$, $ksql$(2x - 1)e^x + c$ksql$, $ksql$F(x) = (2x - 1)\mathrm{e}^{x} + c$ksql$, 2, 3, ARRAY[$ksql$2x e^x - e^x + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (1 - 4x)\mathrm{e}^{2x}$$ksql$, $ksql$(3/2 - 2x)e^(2x) + c$ksql$, $ksql$F(x) = \left(\tfrac{3}{2} - 2x\right)\mathrm{e}^{2x} + c$ksql$, 2, 4, ARRAY[$ksql$(1,5 - 2x)e^(2x) + c$ksql$, $ksql$3/2 e^(2x) - 2x e^(2x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (x + 3)\mathrm{e}^{1 - x}$$ksql$, $ksql$-(x + 4)e^(1 - x) + c$ksql$, $ksql$F(x) = -(x + 4)\mathrm{e}^{1 - x} + c$ksql$, 3, 5, ARRAY[$ksql$-x e^(1 - x) - 4e^(1 - x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = \dfrac{x}{\mathrm{e}^{2x}}$$ksql$, $ksql$-x e^(-2x)/2 - e^(-2x)/4 + c$ksql$, $ksql$F(x) = -\tfrac{1}{2}x\mathrm{e}^{-2x} - \tfrac{1}{4}\mathrm{e}^{-2x} + c$ksql$, 3, 6, ARRAY[$ksql$-1/2 x e^(-2x) - 1/4 e^(-2x) + c$ksql$, $ksql$-(2x + 1)e^(-2x)/4 + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = 6x^{2}\ln(x)$$ksql$, $ksql$2x^3 ln(x) - 2/3 x^3 + c$ksql$, $ksql$F(x) = 2x^{3}\ln(x) - \tfrac{2}{3}x^{3} + c$ksql$, 1, 1, ARRAY[$ksql$2x^3 ln(x) - 2x^3/3 + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(2x)$$ksql$, $ksql$x ln(2x) - x + c$ksql$, $ksql$F(x) = x\ln(2x) - x + c$ksql$, 1, 2, ARRAY[$ksql$x(ln(2x) - 1) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{3}}$$ksql$, $ksql$-ln(x)/(2x^2) - 1/(4x^2) + c$ksql$, $ksql$F(x) = -\dfrac{\ln(x)}{2x^{2}} - \dfrac{1}{4x^{2}} + c$ksql$, 2, 3, ARRAY[$ksql$-1/2 x^-2 ln(x) - 1/4 x^-2 + c$ksql$, $ksql$-(2ln(x) + 1)/(4x^2) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \sqrt{x}\,\ln(x)$$ksql$, $ksql$2/3 x sqrt(x) ln(x) - 4/9 x sqrt(x) + c$ksql$, $ksql$F(x) = \tfrac{2}{3}x\sqrt{x}\,\ln(x) - \tfrac{4}{9}x\sqrt{x} + c$ksql$, 2, 4, ARRAY[$ksql$2x sqrt(x) ln(x)/3 - 4x sqrt(x)/9 + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(x + 1)$$ksql$, $ksql$(x + 1)ln(x + 1) - x + c$ksql$, $ksql$F(x) = (x + 1)\ln(x + 1) - x + c$ksql$, 3, 5, ARRAY[$ksql$(x + 1)ln(x + 1) - x - 1 + c$ksql$, $ksql$x ln(x + 1) + ln(x + 1) - x + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{2}\ln\left(x^{3}\right)$$ksql$, $ksql$x^3 ln(x) - x^3/3 + c$ksql$, $ksql$F(x) = x^{3}\ln(x) - \tfrac{1}{3}x^{3} + c$ksql$, 3, 6, ARRAY[$ksql$x^3 ln(x) - 1/3 x^3 + c$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x\cos(x)\,\mathrm{d}x$$ksql$, $ksql$-2$ksql$, $ksql$-2$ksql$, 1, 1, ARRAY[]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} 2x\cos(x)\,\mathrm{d}x$$ksql$, $ksql$pi - 2$ksql$, $ksql$\pi - 2$ksql$, 1, 2, ARRAY[$ksql$-2 + pi$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} (2x - 1)\cos(x)\,\mathrm{d}x$$ksql$, $ksql$pi - 3$ksql$, $ksql$\pi - 3$ksql$, 2, 3, ARRAY[$ksql$-3 + pi$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, $ksql$pi/4$ksql$, $ksql$\tfrac{1}{4}\pi$ksql$, 2, 4, ARRAY[$ksql$1/4 pi$ksql$, $ksql$0,25pi$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} x\cos(x)\,\mathrm{d}x$$ksql$, $ksql$5/12 pi - 1/2 sqrt(3)$ksql$, $ksql$\tfrac{5}{12}\pi - \tfrac{1}{2}\sqrt{3}$ksql$, 3, 5, ARRAY[$ksql$5pi/12 - sqrt(3)/2$ksql$, $ksql$-1/2 sqrt(3) + 5/12 pi$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{x}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, $ksql$pi/4 - ln(2)/2$ksql$, $ksql$\tfrac{1}{4}\pi - \tfrac{1}{2}\ln(2)$ksql$, 3, 6, ARRAY[$ksql$1/4 pi - 1/2 ln(2)$ksql$, $ksql$-1/2 ln(2) + 1/4 pi$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, $ksql$1$ksql$, $ksql$1$ksql$, 1, 1, ARRAY[]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 3x\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, $ksql$3 - 6/e$ksql$, $ksql$3 - \dfrac{6}{\mathrm{e}}$ksql$, 1, 2, ARRAY[$ksql$3 - 6e^(-1)$ksql$, $ksql$-6/e + 3$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \ln(x)\,\mathrm{d}x$$ksql$, $ksql$1$ksql$, $ksql$1$ksql$, 2, 3, ARRAY[]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} 4x\ln(x)\,\mathrm{d}x$$ksql$, $ksql$e^2 + 1$ksql$, $ksql$\mathrm{e}^{2} + 1$ksql$, 2, 4, ARRAY[$ksql$1 + e^2$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{2} x\mathrm{e}^{\frac{1}{2}x}\,\mathrm{d}x$$ksql$, $ksql$4$ksql$, $ksql$4$ksql$, 3, 5, ARRAY[]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} (2x + 1)\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, $ksql$e^2$ksql$, $ksql$\mathrm{e}^{2}$ksql$, 3, 6, ARRAY[]::text[]),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{x}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$e^2 + 1$ksql$, $ksql$\mathrm{e}^{2} + 1$ksql$, 1, 1, ARRAY[$ksql$1 + e^2$ksql$]::text[]),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sin(x)$ en de $x$-as, tussen de twee opeenvolgende nulpunten $x = 0$ en $x = \pi$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$pi$ksql$, $ksql$\pi$ksql$, 1, 2, ARRAY[]::text[]),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$8ln(2) - 3$ksql$, $ksql$8\ln(2) - 3$ksql$, 2, 3, ARRAY[$ksql$4ln(4) - 3$ksql$, $ksql$-3 + 8ln(2)$ksql$]::text[]),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\cos(x)$ snijdt de $x$-as bij $x = 0$ en bij $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van het vlakdeel $V$ tussen de grafiek en de $x$-as op $\left[0, \tfrac{1}{2}\pi\right]$.$ksql$, $ksql$pi/2 - 1$ksql$, $ksql$\tfrac{1}{2}\pi - 1$ksql$, 2, 4, ARRAY[$ksql$1/2 pi - 1$ksql$, $ksql$-1 + pi/2$ksql$]::text[]),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{2x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\tfrac{1}{4}$. Bereken exact $p$.$ksql$, $ksql$1/2$ksql$, $ksql$p = \tfrac{1}{2}$ksql$, 3, 5, ARRAY[$ksql$p = 1/2$ksql$, $ksql$0,5$ksql$, $ksql$p = 0,5$ksql$]::text[]),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x - 2)\mathrm{e}^{x}$, de $x$-as en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$e^2 - 3$ksql$, $ksql$\mathrm{e}^{2} - 3$ksql$, 3, 6, ARRAY[$ksql$-3 + e^2$ksql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos(2x)$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \cos(2x)$, dus $h(x) = \tfrac{1}{2}\sin(2x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\cos(2x)\,\mathrm{d}x = x \cdot \tfrac{1}{2}\sin(2x) - \int \tfrac{1}{2}\sin(2x) \cdot 1\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos(2x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \tfrac{1}{2}\sin(2x)\,\mathrm{d}x = -\tfrac{1}{4}\cos(2x)$, dus $F(x) = \tfrac{1}{2}x\sin(2x) + \tfrac{1}{4}\cos(2x) + c$. Controle: differentiëren geeft $\tfrac{1}{2}\sin(2x) + x\cos(2x) - \tfrac{1}{2}\sin(2x) = x\cos(2x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = 4x\sin(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = 4x\sin(x)$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \sin(x)$, dus $h(x) = -\cos(x)$, en $g(x) = 4x$, dus $g'(x) = 4$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = 4x\sin(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int 4x\sin(x)\,\mathrm{d}x = 4x \cdot \left(-\cos(x)\right) - \int -\cos(x) \cdot 4\,\mathrm{d}x = -4x\cos(x) + \int 4\cos(x)\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = 4x\sin(x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int 4\cos(x)\,\mathrm{d}x = 4\sin(x)$, dus $F(x) = -4x\cos(x) + 4\sin(x) + c$. Controle: differentiëren geeft $-4\cos(x) + 4x\sin(x) + 4\cos(x) = 4x\sin(x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (4x - 1)\cos(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (4x - 1)\cos(x)$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = 4x - 1$, dus $g'(x) = 4$. De hele haakjesterm gaat in één keer mee als $g$; uitvermenigvuldigen hoeft niet.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (4x - 1)\cos(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int (4x - 1)\cos(x)\,\mathrm{d}x = (4x - 1)\sin(x) - \int \sin(x) \cdot 4\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (4x - 1)\cos(x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int 4\sin(x)\,\mathrm{d}x = -4\cos(x)$, dus $F(x) = (4x - 1)\sin(x) + 4\cos(x) + c$. Controle: differentiëren geeft $4\sin(x) + (4x - 1)\cos(x) - 4\sin(x) = (4x - 1)\cos(x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (2 - x)\sin(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (2 - x)\sin(2x)$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \sin(2x)$, dus $h(x) = -\tfrac{1}{2}\cos(2x)$, en $g(x) = 2 - x$, dus $g'(x) = -1$. Let op het minteken in $g'$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (2 - x)\sin(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int (2 - x)\sin(2x)\,\mathrm{d}x = -\tfrac{1}{2}(2 - x)\cos(2x) - \int -\tfrac{1}{2}\cos(2x) \cdot (-1)\,\mathrm{d}x = -\tfrac{1}{2}(2 - x)\cos(2x) - \int \tfrac{1}{2}\cos(2x)\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (2 - x)\sin(2x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \tfrac{1}{2}\cos(2x)\,\mathrm{d}x = \tfrac{1}{4}\sin(2x)$, dus $F(x) = -\tfrac{1}{2}(2 - x)\cos(2x) - \tfrac{1}{4}\sin(2x) + c$. Controle: differentiëren geeft $\tfrac{1}{2}\cos(2x) + (2 - x)\sin(2x) - \tfrac{1}{2}\cos(2x) = (2 - x)\sin(2x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(x)\cos(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: drie factoren, dus eerst herschrijven. Met de formule $\sin(2x) = 2\sin(x)\cos(x)$ worden de twee gonio's er één, en dan staat er weer een veelterm maal een gonio → partieel integreren.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(x)\cos(x)$$ksql$, 1, $ksql$Herschrijf eerst: $x\sin(x)\cos(x) = \tfrac{1}{2}x\sin(2x)$. Noem daarna $h'(x) = \tfrac{1}{2}\sin(2x)$, dus $h(x) = -\tfrac{1}{4}\cos(2x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(x)\cos(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \tfrac{1}{2}x\sin(2x)\,\mathrm{d}x = -\tfrac{1}{4}x\cos(2x) + \int \tfrac{1}{4}\cos(2x)\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(x)\cos(x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \tfrac{1}{4}\cos(2x)\,\mathrm{d}x = \tfrac{1}{8}\sin(2x)$, dus $F(x) = -\tfrac{1}{4}x\cos(2x) + \tfrac{1}{8}\sin(2x) + c$. Controle: differentiëren geeft $-\tfrac{1}{4}\cos(2x) + \tfrac{1}{2}x\sin(2x) + \tfrac{1}{4}\cos(2x) = \tfrac{1}{2}x\sin(2x) = x\sin(x)\cos(x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos^{2}(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kwadraat van een cosinus, en daar is geen standaardprimitieve van. Haal het kwadraat eerst weg met $\cos^{2}(x) = \tfrac{1}{2} + \tfrac{1}{2}\cos(2x)$; dan blijft er een veelterm maal een gonio over → partieel integreren.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos^{2}(x)$$ksql$, 1, $ksql$Herschrijf eerst: $x\cos^{2}(x) = \tfrac{1}{2}x + \tfrac{1}{2}x\cos(2x)$. De eerste term primitiveer je gewoon. Voor de tweede: $h'(x) = \tfrac{1}{2}\cos(2x)$, dus $h(x) = \tfrac{1}{4}\sin(2x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos^{2}(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \tfrac{1}{2}x\cos(2x)\,\mathrm{d}x = \tfrac{1}{4}x\sin(2x) - \int \tfrac{1}{4}\sin(2x)\,\mathrm{d}x$, en de losse term geeft $\int \tfrac{1}{2}x\,\mathrm{d}x = \tfrac{1}{4}x^{2}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\cos^{2}(x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \tfrac{1}{4}\sin(2x)\,\mathrm{d}x = -\tfrac{1}{8}\cos(2x)$, dus $F(x) = \tfrac{1}{4}x^{2} + \tfrac{1}{4}x\sin(2x) + \tfrac{1}{8}\cos(2x) + c$. Controle: differentiëren geeft $\tfrac{1}{2}x + \tfrac{1}{4}\sin(2x) + \tfrac{1}{2}x\cos(2x) - \tfrac{1}{4}\sin(2x) = x\left(\tfrac{1}{2} + \tfrac{1}{2}\cos(2x)\right) = x\cos^{2}(x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{3x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{3x}$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \mathrm{e}^{3x}$, dus $h(x) = \tfrac{1}{3}\mathrm{e}^{3x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{3x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\mathrm{e}^{3x}\,\mathrm{d}x = \tfrac{1}{3}x\mathrm{e}^{3x} - \int \tfrac{1}{3}\mathrm{e}^{3x}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{3x}$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \tfrac{1}{3}\mathrm{e}^{3x}\,\mathrm{d}x = \tfrac{1}{9}\mathrm{e}^{3x}$, dus $F(x) = \tfrac{1}{3}x\mathrm{e}^{3x} - \tfrac{1}{9}\mathrm{e}^{3x} + c$. Controle: differentiëren geeft $\tfrac{1}{3}\mathrm{e}^{3x} + x\mathrm{e}^{3x} - \tfrac{1}{3}\mathrm{e}^{3x} = x\mathrm{e}^{3x}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{-x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{-x}$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{-x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\mathrm{e}^{-x}\,\mathrm{d}x = -x\mathrm{e}^{-x} - \int -\mathrm{e}^{-x}\,\mathrm{d}x = -x\mathrm{e}^{-x} + \int \mathrm{e}^{-x}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{-x}$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \mathrm{e}^{-x}\,\mathrm{d}x = -\mathrm{e}^{-x}$, dus $F(x) = -x\mathrm{e}^{-x} - \mathrm{e}^{-x} + c = -(x + 1)\mathrm{e}^{-x} + c$. Controle: differentiëren geeft $-\mathrm{e}^{-x} + (x + 1)\mathrm{e}^{-x} = x\mathrm{e}^{-x}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x + 1)\mathrm{e}^{x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x + 1)\mathrm{e}^{x}$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$, en $g(x) = 2x + 1$, dus $g'(x) = 2$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x + 1)\mathrm{e}^{x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int (2x + 1)\mathrm{e}^{x}\,\mathrm{d}x = (2x + 1)\mathrm{e}^{x} - \int 2\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x + 1)\mathrm{e}^{x}$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int 2\mathrm{e}^{x}\,\mathrm{d}x = 2\mathrm{e}^{x}$, dus $F(x) = (2x + 1)\mathrm{e}^{x} - 2\mathrm{e}^{x} = (2x - 1)\mathrm{e}^{x} + c$. Controle: differentiëren geeft $2\mathrm{e}^{x} + (2x - 1)\mathrm{e}^{x} = (2x + 1)\mathrm{e}^{x}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (1 - 4x)\mathrm{e}^{2x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (1 - 4x)\mathrm{e}^{2x}$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = 1 - 4x$, dus $g'(x) = -4$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (1 - 4x)\mathrm{e}^{2x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int (1 - 4x)\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}(1 - 4x)\mathrm{e}^{2x} - \int \tfrac{1}{2}\mathrm{e}^{2x} \cdot (-4)\,\mathrm{d}x = \tfrac{1}{2}(1 - 4x)\mathrm{e}^{2x} + \int 2\mathrm{e}^{2x}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (1 - 4x)\mathrm{e}^{2x}$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int 2\mathrm{e}^{2x}\,\mathrm{d}x = \mathrm{e}^{2x}$, dus $F(x) = \left(\tfrac{1}{2} - 2x\right)\mathrm{e}^{2x} + \mathrm{e}^{2x} = \left(\tfrac{3}{2} - 2x\right)\mathrm{e}^{2x} + c$. Controle: differentiëren geeft $-2\mathrm{e}^{2x} + (3 - 4x)\mathrm{e}^{2x} = (1 - 4x)\mathrm{e}^{2x}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (x + 3)\mathrm{e}^{1 - x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (x + 3)\mathrm{e}^{1 - x}$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = \mathrm{e}^{1 - x}$. De kern $1 - x$ heeft afgeleide $-1$, dus $h(x) = -\mathrm{e}^{1 - x}$. Verder $g(x) = x + 3$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (x + 3)\mathrm{e}^{1 - x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int (x + 3)\mathrm{e}^{1 - x}\,\mathrm{d}x = -(x + 3)\mathrm{e}^{1 - x} - \int -\mathrm{e}^{1 - x}\,\mathrm{d}x = -(x + 3)\mathrm{e}^{1 - x} + \int \mathrm{e}^{1 - x}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (x + 3)\mathrm{e}^{1 - x}$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \mathrm{e}^{1 - x}\,\mathrm{d}x = -\mathrm{e}^{1 - x}$, dus $F(x) = -(x + 3)\mathrm{e}^{1 - x} - \mathrm{e}^{1 - x} = -(x + 4)\mathrm{e}^{1 - x} + c$. Controle: differentiëren geeft $-\mathrm{e}^{1 - x} + (x + 4)\mathrm{e}^{1 - x} = (x + 3)\mathrm{e}^{1 - x}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = \dfrac{x}{\mathrm{e}^{2x}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een e-macht in de noemer. Er is geen quotiëntregel voor primitiveren, dus schrijf de noemer eerst als een e-macht met een minteken in de exponent. Dan staat er een veelterm maal een e-macht → partieel integreren.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = \dfrac{x}{\mathrm{e}^{2x}}$$ksql$, 1, $ksql$Herschrijf eerst: $\dfrac{x}{\mathrm{e}^{2x}} = x\mathrm{e}^{-2x}$. Noem daarna $h'(x) = \mathrm{e}^{-2x}$, dus $h(x) = -\tfrac{1}{2}\mathrm{e}^{-2x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = \dfrac{x}{\mathrm{e}^{2x}}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\mathrm{e}^{-2x}\,\mathrm{d}x = -\tfrac{1}{2}x\mathrm{e}^{-2x} - \int -\tfrac{1}{2}\mathrm{e}^{-2x}\,\mathrm{d}x = -\tfrac{1}{2}x\mathrm{e}^{-2x} + \int \tfrac{1}{2}\mathrm{e}^{-2x}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = \dfrac{x}{\mathrm{e}^{2x}}$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \tfrac{1}{2}\mathrm{e}^{-2x}\,\mathrm{d}x = -\tfrac{1}{4}\mathrm{e}^{-2x}$, dus $F(x) = -\tfrac{1}{2}x\mathrm{e}^{-2x} - \tfrac{1}{4}\mathrm{e}^{-2x} + c$. Controle: differentiëren geeft $-\tfrac{1}{2}\mathrm{e}^{-2x} + x\mathrm{e}^{-2x} + \tfrac{1}{2}\mathrm{e}^{-2x} = x\mathrm{e}^{-2x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = 6x^{2}\ln(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product met $\ln$ erin → partieel integreren, en wel andersom dan je zou denken: de $\ln$ differentiëer je (dat geeft $\dfrac{1}{x}$, een macht van $x$) en de macht van $x$ primitiveer je.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = 6x^{2}\ln(x)$$ksql$, 1, $ksql$Noem de factor die je eerst primitiveert $h'$ en de andere $g$: $h'(x) = 6x^{2}$, dus $h(x) = 2x^{3}$, en $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = 6x^{2}\ln(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int 6x^{2}\ln(x)\,\mathrm{d}x = 2x^{3}\ln(x) - \int 2x^{3} \cdot \dfrac{1}{x}\,\mathrm{d}x = 2x^{3}\ln(x) - \int 2x^{2}\,\mathrm{d}x$. De $\ln$ is verdwenen — dat is precies de bedoeling.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = 6x^{2}\ln(x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int 2x^{2}\,\mathrm{d}x = \tfrac{2}{3}x^{3}$, dus $F(x) = 2x^{3}\ln(x) - \tfrac{2}{3}x^{3} + c$. Controle: differentiëren geeft $6x^{2}\ln(x) + 2x^{2} - 2x^{2} = 6x^{2}\ln(x)$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kale logaritme, en daar ken je geen standaardprimitieve van. Zie het als een product met $1$: $\ln(2x) = 1 \cdot \ln(2x)$ → partieel integreren, met die $1$ als de factor die je primitiveert.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(2x)$$ksql$, 1, $ksql$Noem $h'(x) = 1$, dus $h(x) = x$, en $g(x) = \ln(2x)$. De kern $2x$ heeft afgeleide $2$, dus $g'(x) = \dfrac{2}{2x} = \dfrac{1}{x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int 1 \cdot \ln(2x)\,\mathrm{d}x = x\ln(2x) - \int x \cdot \dfrac{1}{x}\,\mathrm{d}x = x\ln(2x) - \int 1\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(2x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int 1\,\mathrm{d}x = x$, dus $F(x) = x\ln(2x) - x + c$. Controle: differentiëren geeft $\ln(2x) + x \cdot \dfrac{1}{x} - 1 = \ln(2x)$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{3}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product met $\ln$ erin → partieel integreren, en wel andersom dan je zou denken: de $\ln$ differentiëer je (dat geeft $\dfrac{1}{x}$, een macht van $x$) en de macht van $x$ primitiveer je.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{3}}$$ksql$, 1, $ksql$Schrijf de breuk eerst als een macht: $\dfrac{\ln(x)}{x^{3}} = \ln(x) \cdot x^{-3}$. Noem dan $h'(x) = x^{-3}$, dus $h(x) = -\tfrac{1}{2}x^{-2}$, en $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{3}}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \ln(x) \cdot x^{-3}\,\mathrm{d}x = -\tfrac{1}{2}x^{-2}\ln(x) - \int -\tfrac{1}{2}x^{-2} \cdot \dfrac{1}{x}\,\mathrm{d}x = -\tfrac{1}{2}x^{-2}\ln(x) + \int \tfrac{1}{2}x^{-3}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{3}}$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \tfrac{1}{2}x^{-3}\,\mathrm{d}x = -\tfrac{1}{4}x^{-2}$, dus $F(x) = -\dfrac{\ln(x)}{2x^{2}} - \dfrac{1}{4x^{2}} + c$. Controle: differentiëren geeft $\dfrac{\ln(x)}{x^{3}} - \dfrac{1}{2x^{3}} + \dfrac{1}{2x^{3}} = \dfrac{\ln(x)}{x^{3}}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \sqrt{x}\,\ln(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product met $\ln$ erin → partieel integreren, en wel andersom dan je zou denken: de $\ln$ differentiëer je (dat geeft $\dfrac{1}{x}$, een macht van $x$) en de macht van $x$ primitiveer je.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \sqrt{x}\,\ln(x)$$ksql$, 1, $ksql$Schrijf de wortel eerst als macht: $\sqrt{x} = x^{\frac{1}{2}}$. Noem dan $h'(x) = x^{\frac{1}{2}}$, dus $h(x) = \tfrac{2}{3}x^{\frac{3}{2}}$, en $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \sqrt{x}\,\ln(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x^{\frac{1}{2}}\ln(x)\,\mathrm{d}x = \tfrac{2}{3}x^{\frac{3}{2}}\ln(x) - \int \tfrac{2}{3}x^{\frac{3}{2}} \cdot \dfrac{1}{x}\,\mathrm{d}x = \tfrac{2}{3}x^{\frac{3}{2}}\ln(x) - \int \tfrac{2}{3}x^{\frac{1}{2}}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \sqrt{x}\,\ln(x)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int \tfrac{2}{3}x^{\frac{1}{2}}\,\mathrm{d}x = \tfrac{4}{9}x^{\frac{3}{2}}$, dus $F(x) = \tfrac{2}{3}x\sqrt{x}\,\ln(x) - \tfrac{4}{9}x\sqrt{x} + c$. Controle: differentiëren geeft $\sqrt{x}\,\ln(x) + \tfrac{2}{3}\sqrt{x} - \tfrac{2}{3}\sqrt{x} = \sqrt{x}\,\ln(x)$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(x + 1)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: weer een kale logaritme, dus $\ln(x + 1) = 1 \cdot \ln(x + 1)$ → partieel integreren. De slimmigheid zit in $h$: een primitieve van $1$ is $x$, maar $x + 1$ mag óók, want die scheelt alleen een constante.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(x + 1)$$ksql$, 1, $ksql$Noem $h'(x) = 1$ en kies $h(x) = x + 1$ in plaats van $x$; dat maakt de overgebleven integraal veel eenvoudiger. Verder $g(x) = \ln(x + 1)$, dus $g'(x) = \dfrac{1}{x + 1}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(x + 1)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \ln(x + 1)\,\mathrm{d}x = (x + 1)\ln(x + 1) - \int (x + 1) \cdot \dfrac{1}{x + 1}\,\mathrm{d}x = (x + 1)\ln(x + 1) - \int 1\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \ln(x + 1)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int 1\,\mathrm{d}x = x$, dus $F(x) = (x + 1)\ln(x + 1) - x + c$. Controle: differentiëren geeft $\ln(x + 1) + (x + 1) \cdot \dfrac{1}{x + 1} - 1 = \ln(x + 1)$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{2}\ln\left(x^{3}\right)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van $x$ maal een logaritme, maar met een macht ín de logaritme. Haal die er eerst uit met de rekenregel $\ln\left(x^{3}\right) = 3\ln(x)$; daarna is het gewoon partieel integreren.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{2}\ln\left(x^{3}\right)$$ksql$, 1, $ksql$Herschrijf eerst: $x^{2}\ln\left(x^{3}\right) = 3x^{2}\ln(x)$. Noem daarna $h'(x) = 3x^{2}$, dus $h(x) = x^{3}$, en $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{2}\ln\left(x^{3}\right)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int 3x^{2}\ln(x)\,\mathrm{d}x = x^{3}\ln(x) - \int x^{3} \cdot \dfrac{1}{x}\,\mathrm{d}x = x^{3}\ln(x) - \int x^{2}\,\mathrm{d}x$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{2}\ln\left(x^{3}\right)$$ksql$, 3, $ksql$Bereken wat er overblijft: $\int x^{2}\,\mathrm{d}x = \tfrac{1}{3}x^{3}$, dus $F(x) = x^{3}\ln(x) - \tfrac{1}{3}x^{3} + c$. Controle: differentiëren geeft $3x^{2}\ln(x) + x^{2} - x^{2} = 3x^{2}\ln(x) = x^{2}\ln\left(x^{3}\right)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x\cos(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x\cos(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x\cos(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\cos(x)\,\mathrm{d}x = x\sin(x) - \int \sin(x)\,\mathrm{d}x = x\sin(x) + \cos(x)$, dus een primitieve is $F(x) = x\sin(x) + \cos(x)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\pi} x\cos(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[x\sin(x) + \cos(x)\right]_{0}^{\pi} = \left(\pi \cdot 0 + (-1)\right) - \left(0 + 1\right) = -2$. Dat de uitkomst negatief is klopt: op $\left\langle \tfrac{1}{2}\pi, \pi \right]$ ligt de grafiek onder de $x$-as.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} 2x\cos(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} 2x\cos(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = 2x$, dus $g'(x) = 2$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} 2x\cos(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int 2x\cos(x)\,\mathrm{d}x = 2x\sin(x) - \int 2\sin(x)\,\mathrm{d}x = 2x\sin(x) + 2\cos(x)$, dus een primitieve is $F(x) = 2x\sin(x) + 2\cos(x)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} 2x\cos(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[2x\sin(x) + 2\cos(x)\right]_{0}^{\frac{1}{2}\pi} = \left(\pi \cdot 1 + 0\right) - \left(0 + 2\right) = \pi - 2$. Exact laten staan, dus niet afronden.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} (2x - 1)\cos(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} (2x - 1)\cos(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = 2x - 1$, dus $g'(x) = 2$. De hele haakjesterm gaat in één keer mee als $g$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} (2x - 1)\cos(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int (2x - 1)\cos(x)\,\mathrm{d}x = (2x - 1)\sin(x) - \int 2\sin(x)\,\mathrm{d}x = (2x - 1)\sin(x) + 2\cos(x)$, dus een primitieve is $F(x) = (2x - 1)\sin(x) + 2\cos(x)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} (2x - 1)\cos(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[(2x - 1)\sin(x) + 2\cos(x)\right]_{0}^{\frac{1}{2}\pi} = \left((\pi - 1) \cdot 1 + 0\right) - \left(-1 \cdot 0 + 2\right) = \pi - 3$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \sin(2x)$. De kern $2x$ heeft afgeleide $2$, dus $h(x) = -\tfrac{1}{2}\cos(2x)$. Verder $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\sin(2x)\,\mathrm{d}x = -\tfrac{1}{2}x\cos(2x) + \int \tfrac{1}{2}\cos(2x)\,\mathrm{d}x = -\tfrac{1}{2}x\cos(2x) + \tfrac{1}{4}\sin(2x)$, dus een primitieve is $F(x) = -\tfrac{1}{2}x\cos(2x) + \tfrac{1}{4}\sin(2x)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in; let op dat de hoek $2x$ is, dus bij $x = \tfrac{1}{2}\pi$ hoort $\cos(\pi) = -1$ en $\sin(\pi) = 0$: $\left[-\tfrac{1}{2}x\cos(2x) + \tfrac{1}{4}\sin(2x)\right]_{0}^{\frac{1}{2}\pi} = \tfrac{1}{4}\pi - 0 = \tfrac{1}{4}\pi$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} x\cos(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een sinus of cosinus → partieel integreren. Een gonio primitiveren is net zo makkelijk als de gonio zelf, en de veelterm wordt juist eenvoudiger als je hem differentieert.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} x\cos(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} x\cos(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\cos(x)\,\mathrm{d}x = x\sin(x) - \int \sin(x)\,\mathrm{d}x = x\sin(x) + \cos(x)$, dus een primitieve is $F(x) = x\sin(x) + \cos(x)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} x\cos(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in met de exacte waarden $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$ en $\cos\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}\sqrt{3}$: $\left[x\sin(x) + \cos(x)\right]_{\frac{1}{6}\pi}^{\frac{1}{2}\pi} = \left(\tfrac{1}{2}\pi + 0\right) - \left(\tfrac{1}{12}\pi + \tfrac{1}{2}\sqrt{3}\right) = \tfrac{5}{12}\pi - \tfrac{1}{2}\sqrt{3}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{x}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een veelterm maal $\dfrac{1}{\cos^{2}(x)}$ → partieel integreren. Je moet hier wel weten dat $\dfrac{1}{\cos^{2}(x)}$ de afgeleide van $\tan(x)$ is, dus dat die factor zich makkelijk laat primitiveren.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{x}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \dfrac{1}{\cos^{2}(x)}$, dus $h(x) = \tan(x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{x}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \dfrac{x}{\cos^{2}(x)}\,\mathrm{d}x = x\tan(x) - \int \tan(x)\,\mathrm{d}x$. Die laatste integraal ken je uit K.1 B: met de kern $g(x) = \cos(x)$ is $\int \tan(x)\,\mathrm{d}x = -\ln|\cos(x)|$. Dus een primitieve is $F(x) = x\tan(x) + \ln|\cos(x)|$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} \dfrac{x}{\cos^{2}(x)}\,\mathrm{d}x$$ksql$, 3, $ksql$Op $\left[0, \tfrac{1}{4}\pi\right]$ is $\cos(x)$ positief, dus de strepen mogen weg. Vul in: $\left[x\tan(x) + \ln(\cos(x))\right]_{0}^{\frac{1}{4}\pi} = \left(\tfrac{1}{4}\pi \cdot 1 + \ln\left(\tfrac{1}{2}\sqrt{2}\right)\right) - \left(0 + \ln(1)\right) = \tfrac{1}{4}\pi - \tfrac{1}{2}\ln(2)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\mathrm{e}^{x}\,\mathrm{d}x = x\mathrm{e}^{x} - \int \mathrm{e}^{x}\,\mathrm{d}x = x\mathrm{e}^{x} - \mathrm{e}^{x}$, dus een primitieve is $F(x) = (x - 1)\mathrm{e}^{x}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[(x - 1)\mathrm{e}^{x}\right]_{0}^{1} = 0 \cdot \mathrm{e} - (-1) \cdot 1 = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 3x\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 3x\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = 3x$, dus $g'(x) = 3$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 3x\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int 3x\mathrm{e}^{-x}\,\mathrm{d}x = -3x\mathrm{e}^{-x} + \int 3\mathrm{e}^{-x}\,\mathrm{d}x = -3x\mathrm{e}^{-x} - 3\mathrm{e}^{-x}$, dus een primitieve is $F(x) = -3(x + 1)\mathrm{e}^{-x}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 3x\mathrm{e}^{-x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[-3(x + 1)\mathrm{e}^{-x}\right]_{0}^{1} = -6\mathrm{e}^{-1} - (-3) = 3 - \dfrac{6}{\mathrm{e}}$. Exact laten staan.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \ln(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een kale logaritme. Zie het als $1 \cdot \ln(x)$ → partieel integreren, met de $1$ als de factor die je primitiveert.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \ln(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = 1$, dus $h(x) = x$, en $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \ln(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \ln(x)\,\mathrm{d}x = x\ln(x) - \int x \cdot \dfrac{1}{x}\,\mathrm{d}x = x\ln(x) - x$, dus een primitieve is $F(x) = x\ln(x) - x$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} \ln(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in, met $\ln(\mathrm{e}) = 1$ en $\ln(1) = 0$: $\left[x\ln(x) - x\right]_{1}^{\mathrm{e}} = (\mathrm{e} - \mathrm{e}) - (0 - 1) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} 4x\ln(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product met $\ln$ erin → partieel integreren, en wel andersom dan je zou denken: de $\ln$ differentiëer je (dat geeft $\dfrac{1}{x}$, een macht van $x$) en de macht van $x$ primitiveer je.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} 4x\ln(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = 4x$, dus $h(x) = 2x^{2}$, en $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} 4x\ln(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int 4x\ln(x)\,\mathrm{d}x = 2x^{2}\ln(x) - \int 2x^{2} \cdot \dfrac{1}{x}\,\mathrm{d}x = 2x^{2}\ln(x) - \int 2x\,\mathrm{d}x = 2x^{2}\ln(x) - x^{2}$, dus een primitieve is $F(x) = 2x^{2}\ln(x) - x^{2}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} 4x\ln(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[2x^{2}\ln(x) - x^{2}\right]_{1}^{\mathrm{e}} = \left(2\mathrm{e}^{2} - \mathrm{e}^{2}\right) - (0 - 1) = \mathrm{e}^{2} + 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{2} x\mathrm{e}^{\frac{1}{2}x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{2} x\mathrm{e}^{\frac{1}{2}x}\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \mathrm{e}^{\frac{1}{2}x}$. De kern $\tfrac{1}{2}x$ heeft afgeleide $\tfrac{1}{2}$, dus $h(x) = 2\mathrm{e}^{\frac{1}{2}x}$. Verder $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{2} x\mathrm{e}^{\frac{1}{2}x}\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int x\mathrm{e}^{\frac{1}{2}x}\,\mathrm{d}x = 2x\mathrm{e}^{\frac{1}{2}x} - \int 2\mathrm{e}^{\frac{1}{2}x}\,\mathrm{d}x = 2x\mathrm{e}^{\frac{1}{2}x} - 4\mathrm{e}^{\frac{1}{2}x}$, dus een primitieve is $F(x) = (2x - 4)\mathrm{e}^{\frac{1}{2}x}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{2} x\mathrm{e}^{\frac{1}{2}x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[(2x - 4)\mathrm{e}^{\frac{1}{2}x}\right]_{0}^{2} = 0 \cdot \mathrm{e} - (-4) \cdot 1 = 4$. De e-machten vallen hier helemaal weg.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} (2x + 1)\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal, dus eerst primitiveren en daarna de grenzen invullen. Buitenste schil: een product van een veelterm in $x$ en een e-macht → partieel integreren. Een e-macht primitiveren verandert bijna niets, terwijl de veelterm door het differentiëren simpeler wordt.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} (2x + 1)\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 1, $ksql$Noem $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = 2x + 1$, dus $g'(x) = 2$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} (2x + 1)\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int (2x + 1)\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}(2x + 1)\mathrm{e}^{2x} - \int \mathrm{e}^{2x}\,\mathrm{d}x = \left(x + \tfrac{1}{2}\right)\mathrm{e}^{2x} - \tfrac{1}{2}\mathrm{e}^{2x} = x\mathrm{e}^{2x}$. Een primitieve is dus gewoon $F(x) = x\mathrm{e}^{2x}$ — netter dan je zou verwachten, omdat de integrand precies de afgeleide daarvan is.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} (2x + 1)\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[x\mathrm{e}^{2x}\right]_{0}^{1} = 1 \cdot \mathrm{e}^{2} - 0 = \mathrm{e}^{2}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{x}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: vertaal het verhaaltje naar een integraal. De grafiek snijdt de $x$-as waar $x\mathrm{e}^{x} = 0$; omdat $\mathrm{e}^{x}$ nooit nul is, is dat alleen bij $x = 0$. Tussen $0$ en $2$ ligt de grafiek boven de $x$-as, dus de oppervlakte is $\displaystyle\int_{0}^{2} x\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{x}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een veelterm maal een e-macht → partieel integreren. Noem $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{x}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$, dus $\int x\mathrm{e}^{x}\,\mathrm{d}x = x\mathrm{e}^{x} - \int \mathrm{e}^{x}\,\mathrm{d}x = (x - 1)\mathrm{e}^{x}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{x}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[(x - 1)\mathrm{e}^{x}\right]_{0}^{2} = \mathrm{e}^{2} - (-1) = \mathrm{e}^{2} + 1$. De oppervlakte is $\mathrm{e}^{2} + 1$; exact laten staan.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sin(x)$ en de $x$-as, tussen de twee opeenvolgende nulpunten $x = 0$ en $x = \pi$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: op $\left[0, \pi\right]$ zijn $x$ en $\sin(x)$ allebei niet-negatief, dus ligt de grafiek boven de $x$-as. De oppervlakte is $\displaystyle\int_{0}^{\pi} x\sin(x)\,\mathrm{d}x$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sin(x)$ en de $x$-as, tussen de twee opeenvolgende nulpunten $x = 0$ en $x = \pi$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een veelterm maal een gonio → partieel integreren. Noem $h'(x) = \sin(x)$, dus $h(x) = -\cos(x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sin(x)$ en de $x$-as, tussen de twee opeenvolgende nulpunten $x = 0$ en $x = \pi$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$, dus $\int x\sin(x)\,\mathrm{d}x = -x\cos(x) + \int \cos(x)\,\mathrm{d}x = -x\cos(x) + \sin(x)$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sin(x)$ en de $x$-as, tussen de twee opeenvolgende nulpunten $x = 0$ en $x = \pi$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[\sin(x) - x\cos(x)\right]_{0}^{\pi} = \left(0 - \pi \cdot (-1)\right) - (0 - 0) = \pi$. De oppervlakte is $\pi$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: de grafiek van $\ln$ snijdt de $x$-as bij $x = 1$ en ligt daarna erboven. De oppervlakte is dus $\displaystyle\int_{1}^{4} \ln(x)\,\mathrm{d}x$ — de linkergrens haal je uit het nulpunt, niet uit de opgave.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een kale logaritme, dus schrijf $\ln(x) = 1 \cdot \ln(x)$ → partieel integreren. Noem $h'(x) = 1$, dus $h(x) = x$, en $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$, dus $\int \ln(x)\,\mathrm{d}x = x\ln(x) - \int 1\,\mathrm{d}x = x\ln(x) - x$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln(x)$, de $x$-as en de lijn $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[x\ln(x) - x\right]_{1}^{4} = \left(4\ln(4) - 4\right) - (0 - 1) = 4\ln(4) - 3$. Met $\ln(4) = 2\ln(2)$ is dat $8\ln(2) - 3$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\cos(x)$ snijdt de $x$-as bij $x = 0$ en bij $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van het vlakdeel $V$ tussen de grafiek en de $x$-as op $\left[0, \tfrac{1}{2}\pi\right]$.$ksql$, 0, $ksql$Deel 1 van de driedeling: op $\left[0, \tfrac{1}{2}\pi\right]$ zijn $x$ en $\cos(x)$ allebei niet-negatief, dus ligt de grafiek boven de $x$-as. De oppervlakte is $\displaystyle\int_{0}^{\frac{1}{2}\pi} x\cos(x)\,\mathrm{d}x$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\cos(x)$ snijdt de $x$-as bij $x = 0$ en bij $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van het vlakdeel $V$ tussen de grafiek en de $x$-as op $\left[0, \tfrac{1}{2}\pi\right]$.$ksql$, 1, $ksql$Deel 2: een veelterm maal een gonio → partieel integreren. Noem $h'(x) = \cos(x)$, dus $h(x) = \sin(x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\cos(x)$ snijdt de $x$-as bij $x = 0$ en bij $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van het vlakdeel $V$ tussen de grafiek en de $x$-as op $\left[0, \tfrac{1}{2}\pi\right]$.$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$, dus $\int x\cos(x)\,\mathrm{d}x = x\sin(x) - \int \sin(x)\,\mathrm{d}x = x\sin(x) + \cos(x)$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\cos(x)$ snijdt de $x$-as bij $x = 0$ en bij $x = \tfrac{1}{2}\pi$. Bereken exact de oppervlakte van het vlakdeel $V$ tussen de grafiek en de $x$-as op $\left[0, \tfrac{1}{2}\pi\right]$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[x\sin(x) + \cos(x)\right]_{0}^{\frac{1}{2}\pi} = \left(\tfrac{1}{2}\pi + 0\right) - (0 + 1) = \tfrac{1}{2}\pi - 1$. De oppervlakte is $\tfrac{1}{2}\pi - 1$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{2x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\tfrac{1}{4}$. Bereken exact $p$.$ksql$, 0, $ksql$Deel 1 van de driedeling: de grafiek snijdt de $x$-as alleen bij $x = 0$ en ligt daarna erboven, dus de oppervlakte is $\displaystyle\int_{0}^{p} x\mathrm{e}^{2x}\,\mathrm{d}x$, en die moet $\tfrac{1}{4}$ worden.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{2x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\tfrac{1}{4}$. Bereken exact $p$.$ksql$, 1, $ksql$Deel 2: een veelterm maal een e-macht → partieel integreren. Noem $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{2x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\tfrac{1}{4}$. Bereken exact $p$.$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$, dus $\int x\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}x\mathrm{e}^{2x} - \int \tfrac{1}{2}\mathrm{e}^{2x}\,\mathrm{d}x = \tfrac{1}{2}x\mathrm{e}^{2x} - \tfrac{1}{4}\mathrm{e}^{2x}$. Invullen van de grenzen geeft $\left[\tfrac{1}{2}x\mathrm{e}^{2x} - \tfrac{1}{4}\mathrm{e}^{2x}\right]_{0}^{p} = \tfrac{1}{2}p\mathrm{e}^{2p} - \tfrac{1}{4}\mathrm{e}^{2p} + \tfrac{1}{4}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{2x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\tfrac{1}{4}$. Bereken exact $p$.$ksql$, 3, $ksql$Deel 3: los de vergelijking op. Uit $\tfrac{1}{2}p\mathrm{e}^{2p} - \tfrac{1}{4}\mathrm{e}^{2p} + \tfrac{1}{4} = \tfrac{1}{4}$ volgt $\mathrm{e}^{2p}\left(\tfrac{1}{2}p - \tfrac{1}{4}\right) = 0$. Omdat $\mathrm{e}^{2p}$ nooit nul is, moet $\tfrac{1}{2}p = \tfrac{1}{4}$, dus $p = \tfrac{1}{2}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x - 2)\mathrm{e}^{x}$, de $x$-as en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: de grafiek snijdt de $x$-as bij $x = 2$ (want $\mathrm{e}^{x}$ is nooit nul) en de $y$-as is de lijn $x = 0$. Tussen $0$ en $2$ is $x - 2$ negatief, dus ligt de grafiek ónder de $x$-as. De oppervlakte is daarom $-\displaystyle\int_{0}^{2} (x - 2)\mathrm{e}^{x}\,\mathrm{d}x$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x - 2)\mathrm{e}^{x}$, de $x$-as en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2: een veelterm maal een e-macht → partieel integreren. Noem $h'(x) = \mathrm{e}^{x}$, dus $h(x) = \mathrm{e}^{x}$, en $g(x) = x - 2$, dus $g'(x) = 1$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x - 2)\mathrm{e}^{x}$, de $x$-as en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$, dus $\int (x - 2)\mathrm{e}^{x}\,\mathrm{d}x = (x - 2)\mathrm{e}^{x} - \int \mathrm{e}^{x}\,\mathrm{d}x = (x - 3)\mathrm{e}^{x}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x - 2)\mathrm{e}^{x}$, de $x$-as en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[(x - 3)\mathrm{e}^{x}\right]_{0}^{2} = -\mathrm{e}^{2} - (-3) = 3 - \mathrm{e}^{2}$. Die uitkomst is negatief; de oppervlakte is het tegengestelde, dus $\mathrm{e}^{2} - 3$.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2a_macht_gonio' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2a_partieel' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2a_macht_gonio hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2a_macht_e' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2a_partieel' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2a_macht_e hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2a_ln' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2a_partieel' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2a_ln hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2a_bepaald_gonio' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2a_bepaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2a_bepaald_gonio hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2a_bepaald_e_ln' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2a_bepaald' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2a_bepaald_e_ln hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k2a_opp' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k2a_toepassingen' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k2a_opp hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('k2a_partieel', 'k2a_bepaald', 'k2a_toepassingen');
  IF n <> 144 THEN RAISE EXCEPTION 'Deze topics horen samen 144 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
